/bin/zsh -lc "python -c 'from pathlib import Path
from openpyxl import load_workbook
for p in sorted(Path(\"cancer-dependency-rsi/data/raw/sanger_supp\").glob(\"*.xlsx\")):
 w=load_workbook(p,read_only=True,data_only=True)
 print(p.name)
 for s in w:
  print(s.title,s.max_row,s.max_column)
  for row in s.iter_rows(min_row=1,max_row=min(s.max_row or 0,3),values_only=True):
   print([str(c)[:160] for c in row[:12]])
 w.close()'"

